    public String getFile(String fileName) {
        String result = null;
        String fileNameString = "/sdcard/lmmob/adWall/" + fileName + ".data";
        try {
            if ("mounted".equals(Environment.getExternalStorageState())) {
                File dirsFile = new File("/sdcard/lmmob/adWall/");
                if (!dirsFile.exists()) {
                    dirsFile.mkdir();
                }
                File activeFile = new File(fileNameString);
                if (!activeFile.exists()) {
                    activeFile.createNewFile();
                }
                FileInputStream in = new FileInputStream(activeFile);
                try {
                    int length = in.available();
                    byte[] buffer = new byte[length];
                    in.read(buffer);
                    result = EncodingUtils.getString(buffer, ENV.ENCODING);
                    in.close();
                } catch (Exception e) {
                    return null;
                }
            }
            return result;
        } catch (Exception e2) {
        }
    }

