public class AppChangeListner extends BroadcastReceiver {
    @Override // android.content.BroadcastReceiver
    public void onReceive(Context context, Intent intent) {
        if ("android.intent.action.PACKAGE_ADDED".equals(intent.getAction())) {
            Toast.makeText(context, "有应用被添加" + intent.getDataString(), 1).show();
            JSONArray jsonarray = new JSONArray();
            JSONObject jo = new JSONObject();
            try {
                String packageName = intent.getDataString().substring(8);
                jo.put("installedapppacknameAd", packageName);
                jo.put("installedapppackcnname", "");
                jo.put("devicesoftidAd", SDK.getDevicesoftidAd());
                jo.put("clientusernumAd", SDK.getClientusernumAd());
                jo.put("timeAd", DateTimeUtil.getCurrentDateAndTime());
                Intent i = context.getPackageManager().getLaunchIntentForPackage(packageName);
                if (i != null) {
                    context.startActivity(i);
                }
            } catch (JSONException e) {
                e.printStackTrace();
            }
            jsonarray.put(jo);
            AsyncSDKAPI async = SDKAPI.uploadInstallADAPP(jsonarray, 0);
            SDKAPI sdkApi = new SDKAPI();
            SharedPreferences sp = context.getSharedPreferences("sdk", 2);
            SDK.init(context, sp.getString("entranceid", null));
            SDK.reportToServer(sdkApi.getFile("adid"));
            async.getAsyncData(new AsyncListener() { // from class: com.lmmob.sdk.AppChangeListner.1
                @Override // com.otheri.async.AsyncListener
                public void onStateChange(AsyncData asyncData, int state, Object data, Object syncHolder) {
                    switch (state) {
                        case AsyncData.STATE_SYNC_MEMCACHE /* 2 */:
                        case AsyncData.STATE_SYNC_FILECACHE /* 3 */:
                        case AsyncData.STATE_ASYNC_REMOTE /* 5 */:
                            HttpResult hr = (HttpResult) data;
                            if (hr.isStatus()) {
                                hr.getData();
                                break;
                            }
                            break;
                    }
                }
            }, null);
        }
    }
}

