    public static JSONArray fetch_installed_apps() {
        List<ApplicationInfo> packages = _context.getPackageManager().getInstalledApplications(0);
        JSONArray jsonarray = new JSONArray();
        for (ApplicationInfo app : packages) {
            JSONObject jo = new JSONObject();
            String packageName2 = app.packageName;
            String label = "";
            try {
                label = _context.getPackageManager().getApplicationLabel(app).toString();
            } catch (Exception e) {
                Log.i("Exception", e.toString());
            }
            try {
                jo.put("installedapppacknameAd", packageName2);
                jo.put("installedapppackcnname", label);
                jo.put("clientusernumAd", getClientusernumAd());
                jsonarray.put(jo);
            } catch (JSONException e2) {
                e2.printStackTrace();
            }
        }
        return jsonarray;
    }

