package com.lmmob.sdk.util;

public class DateTimeUtil {
    public static String getTimeStampStr() {
        return getDateTime("yyyyMMddHHmmssSSS");
    }

    public static String getCurrentDateAndTime() {
        return getDateTime("yyyy-MM-dd HH:mm:ss");
    }

    public static String getCurrentDate() {
        return getDateTime("yyyy-MM-dd");
    }

    public static String getCurrentTime() {
        String date = getDateTime("HH:mm:ss");
        return date;
    }

    public static long getTimestamp() {
        Date dateNow = new Date();
        return dateNow.getTime();
    }

    public static Date StringToDate(String str) {
        DateFormat format1 = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        try {
            Date date = format1.parse(str);
            return date;
        } catch (ParseException e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String getDateTime(String pattern) {
        if (pattern == null || "".equals(pattern)) {
            pattern = "yyyy-MM-dd HH:mm:ss";
        }
        SimpleDateFormat sdf = new SimpleDateFormat(pattern);
        String dt = sdf.format(new Date());
        return dt;
    }

    public static String dateToString(Date date, String... pattern) {
        String pattern2 = "yyyy-MM-dd HH:mm:ss";
        if (pattern.length > 0) {
            pattern2 = pattern[0];
        }
        DateFormat format1 = new SimpleDateFormat(pattern2);
        return format1.format(date);
    }

    public static List<String> getDateList(Date start, Date end, String... pattern) {
        List<String> ret = new ArrayList<>();
        String pattern2 = "yyyy-MM-dd";
        if (pattern.length > 0) {
            pattern2 = pattern[0];
        }
        while (start.compareTo(end) <= 0) {
            ret.add(dateToString(start, pattern2));
            start.setDate(start.getDate() + 1);
        }
        return ret;
    }

    public static Date stringToDate(String datestr, String... pattern) {
        String pattern2 = "yyyy-MM-dd HH:mm:ss";
        if (pattern.length > 0) {
            pattern2 = pattern[0];
        }
        DateFormat format1 = new SimpleDateFormat(pattern2);
        try {
            Date date = format1.parse(datestr);
            return date;
        } catch (ParseException e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String getLastMonthDateAndTime() {
        String month;
        String year = getDateTime("yyyy");
        String month2 = getDateTime("MM");
        if (Integer.parseInt(month2) > 1) {
            month = String.valueOf(Integer.parseInt(month2) - 1);
            if (month.length() == 1) {
                month = "0" + month;
            }
        } else {
            month = "12";
            year = String.valueOf(Integer.parseInt(year) - 1);
        }
        String time = getDateTime("-dd HH:mm:ss");
        return String.valueOf(year) + "-" + month + time;
    }

    public static String getSwiftnumber(String prefix) {
        String date = getCurrentDate();
        String[] temp = date.split("-");
        String swiftnumber = String.valueOf(prefix) + temp[0] + temp[1] + temp[2];
        return swiftnumber;
    }

