public class FileCache {
    private static final int CONTEXT_CACHE_SIZE = 32;
    private String cacheFolderPath;
    private File cacheFolderPathFile;
    private HashMap<String, CacheInfo> cacheInfos;
    private File configFile;
    private int maxSize;
    private boolean sdcard;

    private File getFile(String fileName) {
        return this.sdcard ? ENV.getSDCardFile(fileName) : ENV.getContextFile(fileName);
    }

    private String makeFileName(String uri) {
        return String.valueOf(ENV.md5(uri.getBytes())) + ".che";
    }

    public FileCache(String cacheFolderPath, int maxSize) {
        this.maxSize = maxSize;
        this.cacheFolderPath = cacheFolderPath.endsWith("/") ? String.valueOf(cacheFolderPath) + '/' : cacheFolderPath;
        if (maxSize < CONTEXT_CACHE_SIZE) {
        }
        if (Environment.getExternalStorageState().equals("mounted")) {
            Log.e(getClass().getSimpleName(), "cache from sdcard");
            this.sdcard = true;
        } else {
            Log.e(getClass().getSimpleName(), "cache from context");
            this.sdcard = false;
        }
        this.cacheFolderPathFile = getFile(this.cacheFolderPath);
        this.configFile = getFile(String.valueOf(this.cacheFolderPath) + "config.cfg");
        this.cacheInfos = new HashMap<>();
        if (!this.cacheFolderPathFile.exists()) {
            this.cacheFolderPathFile.mkdirs();
            writeCacheInfo();
        } else {
            readCacheInfo();
        }
    }

    private void readCacheInfo() {
        try {
            this.cacheInfos.clear();
            FileInputStream fis = new FileInputStream(this.configFile);
            Input in = new Input(fis);
            int size = in.readInt();
            for (int i = 0; i < size; i++) {
                String key = in.readUTF8();
                String fileName = in.readUTF8();
                long time = in.readLong();
                this.cacheInfos.put(key, new CacheInfo(fileName, time));
            }
        } catch (Exception e) {
            Log.e(getClass().getSimpleName(), e.toString());
        }
    }

    private void writeCacheInfo() {
        try {
            FileOutputStream fos = new FileOutputStream(this.configFile);
            Output out = new Output(fos);
            out.writeInt(this.cacheInfos.size());
            for (Map.Entry<String, CacheInfo> entry : this.cacheInfos.entrySet()) {
                out.writeUTF8(entry.getKey());
                CacheInfo ci = entry.getValue();
                out.writeUTF8(ci.fileName);
                out.writeLong(ci.time);
            }
            out.flush();
            out.close();
        } catch (Exception e) {
            Log.e(getClass().getSimpleName(), e.toString());
        }
    }

    public void clear() {
        this.cacheInfos.clear();
        ENV.deleteFile(this.cacheFolderPathFile);
        this.cacheFolderPathFile.mkdirs();
    }

    public boolean containsKey(String uri) {
        String fileName = makeFileName(uri);
        File file = getFile(String.valueOf(this.cacheFolderPath) + fileName);
        return file.exists();
    }

    public Output streamPut(String uri) throws IOException {
        if (this.cacheInfos.size() >= this.maxSize) {
            Iterator<String> iterator = this.cacheInfos.keySet().iterator();
            int count = 0;
            while (iterator.hasNext()) {
                String k = iterator.next();
                if (count % 3 == 0) {
                    File file = getFile(String.valueOf(this.cacheFolderPath) + this.cacheInfos.get(k).fileName);
                    file.delete();
                    iterator.remove();
                }
                count++;
            }
        }
        String fileName = makeFileName(uri);
        File file2 = getFile(String.valueOf(this.cacheFolderPath) + fileName);
        Output out = new Output(new FileOutputStream(file2));
        this.cacheInfos.put(uri, new CacheInfo(fileName, System.currentTimeMillis()));
        writeCacheInfo();
        return out;
    }

    private boolean isExpire(long cacheTime, CacheInfo ci) {
        return System.currentTimeMillis() - cacheTime >= ci.time;
    }

    public boolean isExpire(String uri, long cacheTime) {
        CacheInfo ci = this.cacheInfos.get(uri);
        return isExpire(cacheTime, ci);
    }

    public Input streamGet(String uri, long cacheTime) throws IOException {
        String fileName = makeFileName(uri);
        File file = getFile(String.valueOf(this.cacheFolderPath) + fileName);
        CacheInfo ci = this.cacheInfos.get(uri);
        if (!file.exists()) {
            throw new IOException("file not exists:" + file.getPath());
        }
        if (ci == null) {
            this.cacheInfos.put(uri, new CacheInfo(fileName, System.currentTimeMillis()));
            writeCacheInfo();
            return new Input(new FileInputStream(file));
        }
        if (isExpire(cacheTime, ci)) {
            throw new IOException("cache timeout:" + file.getPath());
        }
        return new Input(new FileInputStream(file));
    }

    private static class CacheInfo {
        public String fileName;
        public long time;

        public CacheInfo(String fileName, long time) {
            this.fileName = fileName;
            this.time = time;
        }
    }
}

