            Iterator<K> iterator = this.cache.keySet().iterator();
            int count = 0;
            while (iterator.hasNext()) {
                iterator.next();
                if (count % 3 == 0) {
                    iterator.remove();
                }
                count++;
            }
        }
        this.cache.put(key, value);
    }

